definition.text:
export type ConfigReport = {
  brief: ConfigBrief; lens: ConfigLens; evidence: ConfigEvidence; outcome: ConfigOutcome;
  handoff: ConfigDisposition | null;
};

export type AudienceReport = {
  record: AudienceRecord; choice: AudienceChoice; answer: AudienceAnswer;
  prepared: AudiencePrepared | null; receipt: AudienceReceipt | null;
};

export type RetainedMemoryReport = {
  brief: MemoryBrief; plan: MemoryPlan; evidence: MemoryEvidence; outcome: MemoryOutcome; handoff: MemoryNote | null;
};

export type UnitHandoffReport = {
  decision: "reviewed" | "staged" | "held";
  plan: UnitHandoffPlan;
  observation: UnitHandoffObservation | null;
  design: UnitDesignHandoff | null;
  identity: UnitIdentityReport | null;
  reason: string;
};

export type SpecialistGoalReport = {
  plan: SpecialistPlan;
  membership: MembershipWitness | null;
  history: HistoryReview | null;
  handoff: IntegrationArtifact | null;
};

export type DictationGoalReport = {
  plan: DictationPlan;
  review: DictationDraftWitness | null;
  handoff: DictationArtifact | null;
};

export type ProviderGoalReport = Report & {
  reviews: { approval: ApprovalReviewEvidence; delivery: DeliveryReviewEvidence };
};

export type RecoveryHandoffOutcome = {
  status: ScratchStatus | "held-eval" | "held-policy";
  recovery: EvalReport;
  directive: Directive;
  handoff: {
    status: ScratchStatus;
    artifact: { path: string; bytes: number } | null;
    missingSources: string[];
    unanswered: string[];
  } | null;
  reason: string;
};

export type TerminalGoalReport = {
  initial: Screen;
  events: TerminalEvent[];
  checkReport: TerminalCheckReport | null;
  discovery: TerminalDiscovery | null;
  handoff: TerminalHandoff | null;
  summary: TerminalSummary;
};

export type LocalReconciliationGoalReport = {
  integration: { status: "integrated" | "held"; head: string; reason: string };
  window: { title: string; window: "open" | "pending" | "closed"; note: string; head: string };
  handoff: { status: "none" | "held" | "staged"; artifact: { path: string; bytes: number } | null };
  archive?: {
    prior: { id: string; title: string; revision: string; setting: string; key: string; value: unknown; sha256: string };
    current: { exists: boolean; value: unknown };
    relation: "matches" | "changed";
  } | null;
};

export type RecoveryReport = {
  task: string;
  revision: number;
  status: TaskStatus;
  original: MessageReceipt | null;
  delivery: OwnerDelivery | null;
  reason: string;
} | { task: null; reason: string };

export type DurableQuestionReport = {
  historyReceipt: string;
  rosterReceipt: string;
  channelId: string;
  question: DurableQuestionJudgment;
  participant: DurableParticipantJudgment;
  disposition: "ready" | "hold";
  explanation: string;
};

export type ClientDiagnosticsReport = {
  views: ClientView[];
  effects: ClientActionReceipt[];
  channel: ChannelReview | null;
  decision: ClientDecision;
  handoff: ClientHandoff | null;
};

export type ScheduledOutcome = {
  schedule: Schedule; authorization: Receipt | null; delivery: Receipt | null; reason: string;
};

export type RecoveryReport =
  | { status: "unresolved"; reason: string }
  | {
    status: "healthy" | "recovered" | "attention" | "inconclusive" | "held";
    surfaceId: string;
    initial: PanelHealthAssessment;
    final: PanelHealthAssessment;
    effects: RecoveryEffect[];
    reason: string;
  };

export type OwnedPreviewReport =
  | {
      status: "published" | "held" | "incomplete";
      targetId: string;
      reason: string | null;
      preflight: PublishPreflightReport | null;
      receipt: OwnedPreviewReceipt | null;
      hosted: OwnedPreviewReadback | null;
    }
  | { status: "unresolved"; reason: string };

export type PdfGoalReport =
  | {
    status: "inspected";
    document: PdfGoalFile;
    selection: PdfGoalSelection;
    missingPages: number[];
    text: PdfIntakeReport | null;
    layouts: PdfLayoutReport[];
    rendered: PdfGoalRender[];
    recommendation: PdfGoalRecommendation;
  }
  | { status: "blocked"; reason: string };

export type PublicationGoalReport =
  | {
      status: "reviewed";
      choice: PublicationGoalChoice;
      preflight: PublishPreflightReport | null;
      revision: PublicationRevisionReport | null;
    }
  | { status: "blocked"; reason: string };
